fn run<T: Json>(data: &[u8]) -> String {
    match unmarshal::<T>(data) {
        Ok(v) => match marshal(&v) {
            Ok(s) => format!("OK {s}"),
            Err(e) => format!("MERR {e}"),
        },
        Err(e) => format!("ERR {}", e.to_string().replace('\n', "\\n")),
    }
}
